'use strict';
const state={foods:[],category:'',selected:'',map:null,markers:[],popup:null};
const $=id=>document.getElementById(id);
const icons={'Street food':'🥟','Noodles':'🍜','Desserts':'🍮','Coffee':'☕','Meals':'🍲','BBQ':'🍢'};
// These exact legacy feed values are protocol data, not interface labels.
const legacyCategories={'\u5c0f\u5403':'Street food','\u9762\u9986':'Noodles','\u751c\u54c1':'Desserts','\u5496\u5561':'Coffee','\u6b63\u9910':'Meals','\u70e7\u70e4':'BBQ','\u7f8e\u98df':'Food'};
const hasHan=value=>/[\u3400-\u4dbf\u4e00-\u9fff\uf900-\ufaff]/.test(String(value||''));
function normalizeFood(food){const result={...food};result.category=legacyCategories[food.category]||(hasHan(food.category)?'Food':String(food.category||'Food'));if(hasHan(food.note))result.note='A place shared on the public food map. See the original recommendation for details.';const href=safeLink(food.source_url);if(href&&new URL(href).hostname==='cachetide.top')result.source_name='CacheTide';else if(hasHan(food.source_name))result.source_name='Original recommendation';return result;}
function el(tag,cls,content){const node=document.createElement(tag);if(cls)node.className=cls;if(content!==undefined)node.textContent=content;return node;}
function visible(){const query=$('search').value.trim().toLocaleLowerCase();return state.foods.filter(f=>(!state.category||f.category===state.category)&&(!$('city').value||f.city===$('city').value)&&(!query||[f.name,f.city,f.category,f.note].join(' ').toLocaleLowerCase().includes(query)));}
function safeLink(value){try{const url=new URL(value);return url.protocol==='https:'&&!url.username&&!url.password?url.href:null;}catch{return null;}}
function selectFood(food){state.selected=food.id;document.querySelectorAll('.foodCard').forEach(card=>card.classList.toggle('selected',card.dataset.id===food.id));if(!state.map)return;const point=food.location.split(',').map(Number);state.map.setZoomAndCenter(15,point);const content=el('article','popup');content.append(el('h3','',food.name),el('div','',`${food.city} · ${food.category}`),el('p','',food.note),el('small','',food.address));const href=safeLink(food.source_url);if(href){const link=el('a','',`${food.source_name||'Original recommendation'} ↗`);link.href=href;link.target='_blank';link.rel='noopener noreferrer';content.append(document.createElement('br'),link);}if(state.popup)state.popup.close();state.popup=new AMap.InfoWindow({content,offset:new AMap.Pixel(0,-24)});state.popup.on('close',()=>{document.querySelector('.mapHeading').style.visibility='visible';});document.querySelector('.mapHeading').style.visibility='hidden';state.popup.open(state.map,point);}
function render(){const rows=visible();$('resultCount').textContent=rows.length;$('mapStats').textContent=state.foods.length?`${state.foods.length} places · ${new Set(state.foods.map(f=>f.city)).size} cities`:'Start with one real place';$('results').replaceChildren();if(!rows.length){const empty=el('div','empty');empty.append(el('strong','',state.foods.length?'No matches this time':'The first good find is yours.'),el('span','',state.foods.length?'Try another city or search term.':'No places yet. Nothing invented, just room for your recommendations. Choose How to contribute to share a favorite.'));$('results').append(empty);}rows.forEach(food=>{const card=el('button','foodCard');card.type='button';card.dataset.id=food.id;card.classList.toggle('selected',food.id===state.selected);const top=el('div','foodTop');const info=el('div');info.append(el('div','foodName',food.name),el('div','foodCity',`${food.city} / ${food.category}`));top.append(el('span','foodIcon',icons[food.category]||'🍽️'),info);card.append(top,el('p','',food.note));card.addEventListener('click',()=>selectFood(food));$('results').append(card);});if(state.map){state.map.remove(state.markers);state.markers=rows.map((food,index)=>{const marker=new AMap.Marker({position:food.location.split(',').map(Number),content:el('div','marker',String(index+1)),anchor:'bottom-center',title:food.name});marker.on('click',()=>selectFood(food));return marker;});state.map.add(state.markers);}}
function categories(){const values=['',...new Set(state.foods.map(food=>food.category))];if(values.length===1)values.push('Street food','Noodles','Desserts','Meals','Coffee');$('categories').replaceChildren();values.forEach(value=>{const button=el('button',value===state.category?'selected':'',value||'All');button.type='button';button.setAttribute('aria-pressed',String(value===state.category));button.onclick=()=>{state.category=value;categories();render();};$('categories').append(button);});const current=$('city').value;$('city').replaceChildren(new Option('All cities',''));[...new Set(state.foods.map(food=>food.city))].sort().forEach(city=>$('city').append(new Option(city,city)));$('city').value=current;}
async function load(){try{const response=await fetch('/api/foods',{cache:'no-store'});if(!response.ok)throw new Error('The directory is temporarily unavailable');const data=await response.json();if(!Array.isArray(data.foods))throw new Error('The directory returned an invalid format');state.foods=data.foods.filter(food=>food&&typeof food.id==='string'&&typeof food.name==='string'&&/^\d+(?:\.\d+)?,\d+(?:\.\d+)?$/.test(food.location)).map(normalizeFood);categories();render();}catch(error){$('results').replaceChildren(el('p','empty',error.message+'. Please try Refresh list again later.'));}}
async function loadMap(){try{const response=await fetch('/api/map-config');if(!response.ok)throw new Error('Map configuration is temporarily unavailable');const config=await response.json();if(!config.key)throw new Error('No Amap JS key is configured. The place list is still available.');window._AMapSecurityConfig={serviceHost:location.origin+'/_AMapService'};const script=document.createElement('script');script.src='https://webapi.amap.com/maps?v=2.0&key='+encodeURIComponent(config.key);await new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(new Error('Map loading timed out. The list is still available; check the network and key domain allowlist.')),18000);script.onload=()=>{clearTimeout(timer);resolve();};script.onerror=()=>{clearTimeout(timer);reject(new Error('The map could not load. The place list is still available.'));};document.head.append(script);});if(!window.AMap)throw new Error('Map authorization did not complete. Check the JS key and domain allowlist.');state.map=new AMap.Map('map',{zoom:4,center:[104.2,35.5],viewMode:'2D',resizeEnable:true,languageCode:'en'});state.map.on('error',()=>{$('mapStatus').textContent='The map is temporarily unavailable. Check the key, allowlist and network; the list is still available.';});state.map.on('complete',()=>{$('mapStatus').textContent='';});render();}catch(error){$('mapStatus').textContent=error.message;}}
$('search').addEventListener('input',render);$('city').addEventListener('change',render);$('fitButton').onclick=()=>{if(state.map){if(state.markers.length)state.map.setFitView(state.markers);else state.map.setZoomAndCenter(4,[104.2,35.5]);}};$('reloadButton').onclick=load;$('aboutButton').onclick=()=>$('about').showModal();$('closeAbout').onclick=()=>$('about').close();load();loadMap();
